  "{0} and {1} spend Christian blood against one another. His Holiness would send a nuncio under your protection to seek an honorable peace.": "{0} と {1} は互いにキリスト教徒の血を流します。法王は、名誉ある平和を求めるために、あなたの保護の下に公使を派遣するだろう。",
