  "{0} Before we leave, I can show your crew a freshwater spring hidden above the beach.": "{0} 出発前に、ビーチの上に隠された淡水の泉を乗組員に見せましょう。",
  "{0} Before we leave, I can show your crew where I found edible roots and shellfish.": "{0} 出発前に、食用の根や貝類を見つけた場所を乗組員に案内できます。",
  "{0} believes {1} is within reach. I should find it, then return to {2}.": "{0} は、{1} が手の届くところにあると信じています。それを見つけてから、{2} に戻る必要があります。",
  "{0} bombarded {1} and silenced its guns. The quays remain closed for {2}; you must put back to sea.": "{0} は {1} を砲撃し、砲を沈黙させました。岸壁は{2}の間閉鎖されたままです。海に戻さなければなりません。",
  "{0} Both courts have now spoken. Rome will act upon the counsel you carry home.": "{0} 両裁判所の弁論が終了しました。ローマはあなたが持ち帰る勧告に基づいて行動するでしょう。",
