  "{0} hardtack": "{0} 乾パン",
  "{0} has already been stripped of portable wealth. The battered harbor remains under arms until its defenses recover.": "{0} はすでにポータブルな富を剥奪されています。荒廃した港は、防御が回復するまで武器の下に置かれます。",
  "{0} has become a city. Resupply paid {1} db, but the harbor is under attack.": "{0} は都市になりました。 {1} DB を補給しましたが、港が攻撃を受けています。",
  "{0} has been plundered. Your raiders carry off {1} doubloons, but the city remains under its former flag.": "{0} が略奪されました。襲撃者たちは {1} 個のダブロンを持ち去りましたが、都市は以前の旗のままです。",
  "{0} has drawn grave notice in Rome. A nuncio must deliver": "{0} はローマで重大な注意を呼び起こしました。公使は届けなければならない",
  "{0} has drawn grave notice in Rome. A nuncio must deliver the Pope's admonition, hear the answer, and return before judgment is entered.": "{0} はローマで重大な注意を呼び起こしました。公使は教皇の勧告を伝え、答えを聞き、判決が下される前に戻らなければならない。",
  "{0} has fallen. Its court has accepted concessions and made peace with": "{0} は下落しました。その裁判所は譲歩を受け入れて和解した",
