  "{0} has fallen. Its court has accepted concessions and made peace with every power still fighting it. You brought the war to its end; the treasury will now honor {1}'s extraordinary commission.": "{0} が落ちました。同国の法廷は譲歩を受け入れ、依然として争っているあらゆる勢力と和平を結んだ。あなたは戦争を終わらせました。財務省は今後、{1} の特別な任務を尊重することになります。",
  "{0} has reached {1}.": "{0} が {1} に達しました。",
  "{0} has reached {1}. Speak with the {2} before they go ashore.": "{0} が {1} に達しました。 {2} が上陸する前に話しかけてください。",
  "{0} has received the {1}. Your {2} db is waiting at the treasury.": "{0} は {1} を受け取りました。あなたの {2} DB は財務省で待機しています。",
  "{0} has submitted and peace is signed. Carry the final dispatches to {1}.": "{0} が提出し、和平が署名されました。最後のディスパッチを {1} に運びます。",
  "{0} has surrendered. The captured treasury yields {1} doubloons.{2}{3}": "{0} は降伏しました。占領された国庫からは {1} ダブロンが得られます。{2}{3}",
  "{0} has taken power in {1}. The harbor watch expects policy to follow.": "{0} が {1} の権力を掌握しました。ハーバーウォッチは政策がこれに従うことを期待している。",
  "{0} HELD": "{0} ユニットが保持されています",
