  "{0} I can have it fitted now for {1} doubloons.": "{0} {1} のダブロンに取り付けることができます。",
  "{0} in {1}'s name and force peace. Keep the spoils;": "{0} を {1} の名前にして、平和を強制します。戦利品は保管しておいてください。",
  "{0} is aboard on an embassy from {1} to {2}; finish that mission first.": "{0} は {1} から {2} までの大使館に乗っています。まずはそのミッションを終わらせてください。",
  "{0} is aboard, returning from {1} to {2}; finish that embassy first.": "{0} が乗車し、{1} から {2} に戻ります。まずその大使館を終わらせてください。",
  "{0} is at war with the flag you serve. Attack the harbor batteries, land your marines, and the city can be taken for {1}.": "{0} はあなたが仕える旗と戦争中です。港の砲台を攻撃し、海兵隊を上陸させれば、都市を{1}占領できるでしょう。",
  "{0} is ready for the court at {1}.": "{0} は {1} のコートに向かう準備ができています。",
  "{0} is secure. Paid {1} db.": "{0} は安全です。有料の {1} DB。",
  "{0} is still owed about {1} doubloons.": "{0} にはまだ {1} ダブロンの支払い義務があります。",
  "{0} is still owed about {1} doubloons. Every profitable voyage brings the family estate closer to safety.": "{0} にはまだ {1} ダブロンの支払い義務があります。有益な航海が行われるたびに、家族の財産は安全に近づきます。",
  "{0} is taken. Carry the victory dispatches back to {1}; the crown's debt must be settled there.": "{0} が取得されました。勝利の派遣を{1}に持ち帰ります。王室の借金はそこで解決されなければなりません。",
  "{0} is under attack by the {1}. {2}": "{0} は {1} による攻撃を受けています。 {2}",
  "{0} is waiting aboard for passage to {1}.": "{0} は {1} への通過を船内で待っています。",
  "{0} ISSUES A BULL IN FAVOUR OF {1}": "{0} は {1} を支持して強気銘柄を発行します",
  "{0} JOINED THE CREW": "{0} がクルーに加わりました",
