  "{0} m": "{0} メートル",
  "{0} MARINES LOST": "{0} 海兵隊員が失われました",
  "{0} market. Doubloons {1}. Cargo {2}/{3}.": "{0}市場。ダブロン {1}。貨物 {2}/{3}。",
  "{0} may receive a public mark of Papal favor.": "{0} は教皇の好意の公的マークを受ける可能性があります。",
  "{0} may receive a public mark of Papal favor. His Holiness first wants a captain whose eyes are not those of a courtier.": "{0} は教皇の好意の公的マークを受ける可能性があります。法王はまず、廷臣の目ではない船長を求めておられる。",
  "{0} more day{1}": "{0} あと 1 日{1}",
  "{0} My price remains {1} doubloons.": "{0} 価格は {1} ダブロンのままです。",
  "{0} now answers to {1}. You silenced its guns and kept": "{0} が {1} に回答するようになりました。あなたはその銃を沈黙させて守り続けた",
  "{0} now answers to {1}. You silenced its guns and kept faith with your commission. The treasury will honor the crown's word.": "{0} が {1} に回答するようになりました。あなたはその銃声を沈黙させ、自分の使命を信じ続けました。財務省は国王の言葉を尊重するだろう。",
  "{0} now flies the {1} flag.": "{0} は {1} フラグを立てるようになりました。",
  "{0} Now I want to see beyond this harbor. Give me a berth, and I will make your provisions last.": "{0} 次に、この港の向こうを見たいと思います。私に寝床を与えてください、そうすれば私はあなたの食糧を最後まで作ります。",
  "{0} now rules {1}. A new ruler always means new contracts.": "{0} が {1} を支配するようになりました。新しい統治者は常に新しい契約を意味します。",
  "{0} of {1} creatures now have a place in my book. Keep watch whenever you make landfall.": "{1} 匹中 {0} 匹が私の本の中に登場しました。上陸するときは常に監視してください。",
  "{0} of {1} creatures of these seas now have a place in my book. Keep watch whenever you make landfall.": "これらの海の {1} 匹中 {0} 匹が私の本の中に登場しました。上陸するときは常に監視してください。",
  "{0} of {1} pieces recovered": "{1} 個中 {0} 個を回収しました",
  "{0} of Captain {1}'s old crew still block the harbor.": "{1} 船長の古い乗組員の {0} が依然として港を封鎖しています。",
  "{0} of Captain {1}'s old crew still block the harbor. They mean to have the treasure before they let us reach the quay.": "{1} 船長の古い乗組員の {0} が依然として港を封鎖しています。彼らは私たちを岸壁に着かせる前に宝物を手に入れるつもりだ。",
  "{0} officials receive it under the law of embassies.": "{0} 職員は大使館法に基づいてこの情報を受け取ります。",
