  "{0} PROCLAIMS A CRUSADE AGAINST {1}": "{0} は {1} に対する十字軍を宣言します",
  "{0} Rare gear like this earns its berth on a working ship.": "{0} このような珍しい装備は、現役の船に搭載されています。",
  "{0} RATIONS": "{0} 配給",
  "{0} rebels against {1}.": "{0} は {1} に反抗します。",
  "{0} RELEASED": "{0} リリースされました",
  "{0} remains aboard and can transfer with the prize if its hold has room.": "{0} は船内に留まり、船室に余裕がある場合は賞品と一緒に転送できます。",
  "{0} repelled the landing. We lost {1} crew in the fighting.": "{0} は着地をはね返しました。戦闘で{1}乗組員を失いました。",
  "{0} Return within one year with {1} {2} for {3}, or the venture may still fail.": "{0} 1 年以内に {1} {3} の {2} で復帰します。そうしないと、ベンチャーはまだ失敗する可能性があります。",
  "{0} returned home free of debt and kept the family estate. {1} {2}{3}": "{0} は借金をせずに帰国し、家族の財産を守りました。 {1} {2}{3}",
  "{0} returned with Captain {1}'s treasure. The map was locked away, the gold wisely spent, and no black sail ruled the captain's fate again. {2}{3}": "{0} は {1} 船長の宝物を持って戻ってきました。地図は厳重に保管され、金は賢く使われ、黒い帆が船長の運命を支配することは二度とありませんでした。 {2}{3}",
  "{0} returned with the white whale's story. The chase became legend, but the captain finally learned to live beyond it. {1}{2}": "{0} がシロイルカの話を返してきました。この追跡は伝説となったが、船長はついに追跡を超えて生きることを学んだ。 {1}{2}",
  "{0} Sail away, find {1} {2}, and return before one year has passed.": "{0} 出航し、{1} {2} を見つけて、1 年が経過する前に戻ってきます。",
  "{0} seeks {1}. Carry me to {2} and home again; the treasury will pay {3} db.": "{0} は {1} をシークします。 {2} まで運んで、また家に連れて行ってください。国庫は {3} DB に支払います。",
