  "clinker rivets and roves": "クリンカーリベットとローブ",
  "Closely woven canvas holds its shape in a fresh breeze.": "緻密に織られたキャンバスは、さわやかな風が吹いてもその形を保ちます。",
  "Cloud Cover Performance Benchmark": "雲量パフォーマンスベンチマーク",
  "Cloves drew the Portuguese to your shore. Your family mistook their appetite for a guarantee.": "クローブはポルトガル人を海岸に引き寄せました。あなたの家族は、自分たちの食欲を保証と誤解しました。",
  "CMD": "CMD",
  "Coastal canoe crews recognized your sail offshore. Market runners are already spreading word of your return.": "沿岸カヌーの乗組員は沖合であなたの帆を認識しました。市場関係者はすでにあなたの復帰の噂を広めています。",
  "Coastal Pinnace": "沿岸ピンネース",
  "Coastal Surveyor": "海岸測量士",
  "coastal waters": "沿岸水域",
  "Coasters call with every change of wind, but an unusual cargo can still stir the whole market.": "風が変わるたびにコースターが鳴きますが、珍しい貨物が市場全体を揺るがすこともあります。",
  "Coaxes the ship through turns and closer to the wind.": "旋回中や風に近づく際に船をなだめます。",
  "Cod": "タラ",
  "Coffee first. Then bearings. Then whales.": "まずはコーヒー。次にベアリング。それからクジラ。",
  "Coir Cordage": "コイアコード",
  "Cold": "寒い",
  "Cold, isolation, and scurvy destroyed Saint Croix. De Monts and Poutrincourt will try again in sheltered Annapolis, relying on nearby Mi'kmaq knowledge.": "寒さ、孤立、そして壊血病がセントクロイ島を破壊しました。ド・モンツとプートランクールは、近くにいたミクマク族の知識を頼りに、保護されたアナポリスで再挑戦する予定だ。",
