  "Compact horn-and-sinew bows loose quickly from a crowded deck.": "コンパクトなホーンとシニューの船首は、混雑した甲板からすぐに外れてしまいます。",
  "COMPARE WITH {0}": "{0} と比較してください",
  "Complete a captain's main goal and return home.": "キャプテンの主な目標を達成して家に帰りましょう。",
  "Complete a shore scavenging expedition.": "海岸の清掃遠征を完了する。",
