  "Deliver available ingredients": "入手可能な食材を届ける",
  "Deliver five passengers safely in one voyage.": "1 回の航海で 5 人の乗客を安全に送り届ける。",
  "Delivered {0} x{1}. {2} still needed; these stores buy the colony {3} more days.": "{0} x{1} を配信しました。 {2} がまだ必要です。これらの店は植民地を{3} 日以上購入します。",
