  "R CTRL": "R CTRL",
  "R META": "Rメタ",
  "R SHIFT": "Rシフト",
  "Raccoon": "アライグマ",
  "Raichur's victory procession was splendid. I noticed your paymaster absent from it.": "ライチュールの勝利の行列は素晴らしかった。あなたの給与担当者が不在であることに気づきました。",
  "Rainier loomed above the inland waters, a massive white volcano cut by rivers of ice. Even at great distance it dwarfed the forested ridges in front of it.": "レーニア山は、氷の川によって切り取られた巨大な白い火山として、内陸水の上にそびえ立っていた。遠くから見ても、目の前の森林に覆われた尾根が小さく見えました。",
  "Raise Our Colors": "私たちの色を育てましょう",
  "Reach {0}": "{0} に到達する",
  "Reads shoals and handles a net with confidence.": "浅瀬を読み、自信を持ってネットを扱う。",
  "REALIZED P/L {0} DB": "実現損益 {0} DB",
  "REBELLION: {0} / {1}": "反乱: {0} / {1}",
  "REC {0}:{1}": "REC {0}:{1}",
  "Receive the answer": "答えを受け取る",
  "Recife has become the reef-sheltered warehouse port of Pernambuco. Sugar comes down from the mills, and Atlantic hulls crowd the channel.": "レシフェはペルナンブコ州の岩礁に守られた倉庫港となっています。製糖所からは砂糖が降りてきて、大西洋の船体が海峡に群がります。",
  "Recife needs a full sugar cargo to prove the new harbor can pay.": "レシフェは、新しい港が支払えるかどうかを証明するために、砂糖を満載した貨物を必要としている。",
  "Recite the voyage with the navigators": "航海士と一緒に航海を朗読します",
  "Reconstructed ash and yew bows complete the longship's fighting equipment.": "復元されたトネリコとイチイの弓がロングシップの戦闘装備を完成させます。",
  "Recovered all {0} pieces of Captain {1}'s map, found the island, and fought the old crew home.": "{1} 船長の地図の {0} 個の部分をすべて回収し、島を発見し、古い乗組員と戦って家に帰りました。",
  "Reef fish": "サンゴ礁の魚",
  "reference city": "参考都市",
