  "Rhinoceros": "サイ",
  "Rhodes": "ロードス島",
  "Rhodes has fallen, but the Order's vows have not. His Holiness would have you carry": "ロードス島は陥落しましたが、教団の誓いは陥落しませんでした。法王はあなたに持たせてくださいます",
  "Rhodes has fallen, but the Order's vows have not. His Holiness would have you carry a petition to Charles, King of Spain and Emperor, that Malta be granted as a new seat": "ロードス島は陥落しましたが、教団の誓いは陥落しませんでした。法王はあなたに、スペイン国王であり皇帝でもあるカルロスに、マルタを新たな議席として与えてほしいという嘆願書を持って行くよう求められるだろう。",
  "Rhodes has fallen, but the Order's vows have not. His Holiness would have you carry a petition to Charles, King of Spain and Emperor, that Malta be granted as a new seat{0}": "ロードス島は陥落しましたが、教団の誓いは陥落しませんでした。法王はあなたに、スペイン国王であり皇帝でもあるカルロスに、マルタに新たな議席を与えてほしいという嘆願書を持っていくよう求めています{0}。",
  "Rhodes has fallen, but the Order's vows have not. His Holiness would have you carry a petition to Charles, King of Spain and Emperor, that Malta be granted as a new seat{0}.": "ロードス島は陥落しましたが、教団の誓いは陥落しませんでした。法王はあなたに、スペイン国王であり皇帝でもあるカルロスに、マルタに新たな議席を与えてほしいとの請願書を運ぶよう求めている{0}。",
  "Rhodes is lost behind us. At Birgu we shall raise the eight-pointed cross again, and": "ローズは私たちの後ろで迷っています。ビルグで私たちは再び八角の十字架を掲げます、そして",
  "Rhodes is lost behind us. At Birgu we shall raise the eight-pointed cross again, and make a fortress of our exile.": "ローズは私たちの後ろで迷っています。ビルグで我々は再び八角の十字架を掲げ、追放者の要塞を築くだろう。",
  "Rhodes still stands before the Ottoman sea, but its defenders cannot live on courage alone.": "ロードス島は今もオスマン帝国の海に面していますが、その防衛者たちは勇気だけでは生きていけません。",
  "Rhodes still stands before the Ottoman sea, but its defenders cannot live on courage alone. His Holiness requires a trusted captain to carry sealed pleas for relief.": "ロードス島は今もオスマン帝国の海に面していますが、その防衛者たちは勇気だけでは生きていけません。法王は、信頼できる船長に救済を求める封印された嘆願書を運ぶよう求めている。",
  "RIGHT": "右",
  "Ring; your presence will show that the Order yet lives.": "リング;あなたの存在は、教団がまだ生きていることを示します。",
  "ritual envoy": "儀式の使者",
  "River craft reach this far, but arrivals are uncommon enough that the market knows your cargo before the ropes are tied.": "川船はここまで到達しますが、到着するのは珍しいため、ロープが結ばれる前に市場が貨物を把握します。",
  "River craft, caravans, and sea-going merchants meet here, filling the customs house with a dozen languages.": "川船、キャラバン、航海商人がここに集まり、税関は十数か国語で埋め尽くされます。",
