  "sails, vestments, bedding, and a hospital": "帆、祭服、寝具、病院",
  "Saint Croix taught us to fear cold more than distance. Bring": "セントクロイ島は私たちに、距離よりも寒さを恐れるように教えてくれました。持参する",
  "Sale prices +{0}": "セール価格 +{0}",
