  "Salmon": "サーモン",
  "Salvador needs grain while officials, soldiers, builders, and clergy continue to arrive.": "役人、兵士、建築業者、聖職者が続々と到着する中、サルバドールは穀物を必要としている。",
  "Salvador now stands as Brazil's fortified capital, with government on the heights and Atlantic commerce below.": "サルバドールは現在、ブラジルの要塞首都として立っており、高台に政府があり、下に大西洋の商業が存在します。",
  "Sampan": "Sampan",
  "San Agustin needs grain before storms or war cut off the harbor.": "サン アグスティンには、嵐や戦争で港が遮断される前に穀物が必要です。",
  "sangat singer": "サンガット歌手",
  "Sangat's gift": "サンガットの贈り物",
  "Sanriku whaling grounds": "三陸捕鯨場",
  "Santiago de Leon de Caracas now holds the valley, though its Indigenous name has already proved stronger than the one in the charter.": "現在この渓谷はサンティアゴ デ レオン デ カラカスが所有していますが、その先住民族の名前は憲章にある名前よりも強いことがすでに証明されています。",
  "Sao Paulo de Luanda has become Portugal's fortified Angolan port. Its Atlantic wealth is inseparable from warfare and the traffic in enslaved people.": "サンパウロ デ ルアンダはポルトガルのアンゴラの要塞港となっています。その大西洋の富は、戦争や奴隷化された人々の交通と切り離すことができません。",
  "Sao Sebastiao cannot secure Guanabara without more powder.": "サン・セバスティアンは、さらなる火薬がなければグアナバラを確保することはできない。",
  "Sao Sebastiao has secured Guanabara Bay for Portugal. Around the old redoubt, Rio de Janeiro is becoming a true port.": "サン・セバスティアンはポルトガルのグアナバラ湾を確保した。古い要塞の周囲で、リオデジャネイロは真の港になりつつあります。",
